#!/usr/bin/env node
// Copia todo el proyecto DENTRO de la carpeta donde lo ejecutes (puede ser una carpeta que ya existe).
// Uso:  node instalar-red-de-lideres.mjs
// Si un archivo ya existía y es distinto, el anterior se guarda como .bak
import { gunzipSync } from "node:zlib";
import { mkdirSync, writeFileSync, existsSync, readFileSync, renameSync } from "node:fs";
import { dirname, join } from "node:path";

const DATOS = "";

const tar = gunzipSync(Buffer.from(DATOS, "base64"));
const texto = (b, a, z) => b.subarray(a, z).toString("utf8").replace(/\0.*$/s, "");
let pos = 0, n = 0;
while (pos + 512 <= tar.length) {
  const h = tar.subarray(pos, pos + 512);
  if (h.every((x) => x === 0)) break;
  const prefijo = texto(h, 345, 500);
  const completo = (prefijo ? prefijo + "/" : "") + texto(h, 0, 100);
  const nombre = completo.replace(/^red-de-lideres\/?/, "");
  const tam = parseInt(texto(h, 124, 136).trim() || "0", 8);
  const tipo = String.fromCharCode(h[156] || 48);
  pos += 512;
  if (nombre.split("/").includes("..")) throw new Error("Ruta no válida: " + nombre);
  if (nombre && tipo === "5") mkdirSync(nombre, { recursive: true });
  else if (nombre && tipo === "0") {
    const contenido = tar.subarray(pos, pos + tam);
    mkdirSync(dirname(nombre), { recursive: true });
    if (existsSync(nombre) && !readFileSync(nombre).equals(contenido)) renameSync(nombre, nombre + ".bak");
    writeFileSync(nombre, contenido);
    n++;
  }
  pos += Math.ceil(tam / 512) * 512;
}
console.log("Listo: " + n + " archivos copiados en esta carpeta.");
console.log("Siguiente: npm install  (y lee el README.md)");
